import numpy as np

class NumpyExtensionArray:
    def __init__(self, array):
        self.array = array

    def take(self, indices, allow_fill=False):
        # Determine the fill_value based on dtype
        if allow_fill:
            fill_value = np.nan
        else:
            fill_value = None

        # Create a result array using np.take
        result_array = np.take(self.array, indices, mode='clip' if allow_fill else 'raise')

        # Handle fill value substitution for -1 indices
        if allow_fill:
            result_array = np.where(np.array(indices) == -1, fill_value, result_array)

        # Determine the dtype to return based on the original dtype
        if self.array.dtype == np.bool_:
            # Convert boolean results to dtype=object
            result_array = result_array.astype(object)
        else:
            # Convert numeric results to np.float64
            result_array = result_array.astype(np.float64)

        return result_array
